from utils.common_methods import RUN_CONFIG, get_test_data

class LoginPage:
    def __init__(self, page):
        self.page = page
        page.set_default_timeout(RUN_CONFIG["actionTimeout"])
        page.set_default_navigation_timeout(RUN_CONFIG["navigationTimeout"])
        self.username = page.get_by_placeholder("Username")
        self.password = page.get_by_placeholder("Password")
        self.login_button = page.get_by_role("button", name="Login")
        self.inventory_heading = page.get_by_text("Products", exact=True)

    def open(self): self.page.goto("/")
    def login(self, username, password):
        self.username.fill(username)
        self.password.fill(password)
        self.login_button.click()
    def login_with_valid_credentials(self):
        user = get_test_data()["validUser"]
        self.login(user["username"], user["password"])
